import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const root = resolve(fileURLToPath(new URL("..", import.meta.url)));

const expectedEntryDependencies = new Map([
  ["E0B-001", ["E0A-002"]],
  ["E0C-001", ["E0A-003", "E0B-003"]],
  ["E0D-001", ["E0A-003", "E0C-003"]]
]);

const prdPaths = new Map([
  ["E0B-001", "docs/prd/PRD-E0B-adapter-observability-contract.md"],
  ["E0C-001", "docs/prd/PRD-E0C-pack-time-and-eligibility-simulation.md"],
  ["E0D-001", "docs/prd/PRD-E0D-deterministic-prescription-input-contract.md"]
]);

const expectedPrdPrerequisites = new Map([
  ["E0B-001", ["D0", "E0-A"]],
  ["E0C-001", ["E0-A", "E0-B"]],
  ["E0D-001", ["E0-A", "E0-C"]]
]);

const ticketEpic = (ticketId) => {
  const match = ticketId.match(/^(D0|E0[A-D]|E\d+)-/);
  assert.ok(match, `ticket ID lacks an epic key: ${ticketId}`);
  return match[1];
};

const canonicalPrdEpic = (epic) => epic.replace(/^E0-([A-D])$/, "E0$1");

const parseBoardRows = (board) => {
  const rows = new Map();
  for (const line of board.split(/\r?\n/)) {
    const cells = line.split("|").map((cell) => cell.trim());
    const ticket = cells[1]?.match(/^\[([A-Z0-9-]+)]\([^)]+\)$/)?.[1];
    if (!ticket) continue;
    rows.set(ticket, {
      epic: cells[2],
      dependencies: cells[5] === "None" ? [] : cells[5].split(",").filter(Boolean)
    });
  }
  return rows;
};

const prdPrerequisites = (path) => {
  const text = readFileSync(resolve(root, path), "utf8");
  const line = text.match(/^- Dependencies: (.+)$/m)?.[1];
  assert.ok(line, `${path} has no dependency declaration`);
  return line.split(/[;,]/).map((value) => value.trim()).filter((value) => /^(D0|E0-[A-D])$/.test(value));
};

const upstreamEpics = (ticketId, rows, visited = new Set()) => {
  if (visited.has(ticketId)) return new Set();
  visited.add(ticketId);
  const row = rows.get(ticketId);
  assert.ok(row, `board has no row for dependency ${ticketId}`);
  const result = new Set();
  for (const dependency of row.dependencies) {
    result.add(ticketEpic(dependency));
    for (const epic of upstreamEpics(dependency, rows, visited)) result.add(epic);
  }
  return result;
};

test("the generated board preserves hyphenated E0 PRD prerequisites at epic entry", () => {
  assert.doesNotThrow(() => {
    execFileSync(process.execPath, ["scripts/render-execution-views.mjs", "--check"], {
      cwd: root,
      encoding: "utf8",
      stdio: "pipe"
    });
  }, "the rendered board must agree with its ticket contracts and catalog");

  const rows = parseBoardRows(readFileSync(resolve(root, "docs/tickets/BOARD.md"), "utf8"));

  for (const [ticketId, expectedDependencies] of expectedEntryDependencies) {
    const row = rows.get(ticketId);
    assert.ok(row, `board has no ${ticketId} entry row`);
    assert.deepEqual(row.dependencies, expectedDependencies, `${ticketId} has the wrong direct prerequisites`);

    const declared = prdPrerequisites(prdPaths.get(ticketId));
    assert.deepEqual(declared, expectedPrdPrerequisites.get(ticketId), `${ticketId} PRD prerequisites changed unexpectedly`);

    const reachableEpics = upstreamEpics(ticketId, rows);
    for (const prerequisite of declared) {
      assert.ok(
        reachableEpics.has(canonicalPrdEpic(prerequisite)),
        `${ticketId}'s board dependency graph does not represent PRD prerequisite ${prerequisite}`
      );
    }
  }
});
